function validate([arr]) {
  if (!Array.isArray(arr) || arr.length > 100000) return 'arr holds at most 10^5 values.';
  if (arr.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000)) return 'Each value is an integer between -10^9 and 10^9.';
  return null;
}

