function arrayRankTransform(arr) {
  const distinct = Array.from(new Set(arr));
  const out = [];
  for (const x of arr) {
    let smaller = 0;
    for (const d of distinct) if (d < x) smaller++;
    out.push(smaller + 1);
  }
  return out;
}

