function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const span = rand() < 0.5 ? 1000000000 : 300;
    return [Array.from({ length: n }, () => pick(-span, span))];
  }
  const n = pick(0, 9);
  const span = rand() < 0.6 ? 5 : 1000000000;
  return [Array.from({ length: n }, () => pick(-span, span))];
}
